create table if not exists public.security_trust_provider_observation_v1(observation_id uuid primary key default gen_random_uuid(),tenant_id text not null default 'canonical',provider_key text not null,control_key text not null,category text not null,status text not null check(status in('VERIFIED','PARTIAL','OPEN','UNKNOWN','STALE')),severity text not null default 'medium' check(severity in('critical','high','medium','low','info')),statement text not null,evidence jsonb not null default '{}'::jsonb,source_url text,observed_at timestamptz not null default now(),expires_at timestamptz);create index if not exists security_trust_provider_observation_lookup_idx on public.security_trust_provider_observation_v1(tenant_id,provider_key,control_key,observed_at desc);alter table public.security_trust_provider_observation_v1 enable row level security;revoke all on public.security_trust_provider_observation_v1 from public,anon,authenticated;grant select,insert on public.security_trust_provider_observation_v1 to service_role;
create table if not exists public.security_trust_snapshot_v1(tenant_id text primary key,summary jsonb not null default '{}'::jsonb,domains jsonb not null default '[]'::jsonb,providers jsonb not null default '[]'::jsonb,frameworks jsonb not null default '[]'::jsonb,open_findings jsonb not null default '[]'::jsonb,generated_at timestamptz not null default now());alter table public.security_trust_snapshot_v1 enable row level security;revoke all on public.security_trust_snapshot_v1 from public,anon,authenticated;grant select,insert,update,delete on public.security_trust_snapshot_v1 to service_role;
create or replace function public.record_security_trust_observation_v1(p_tenant_id text,p_provider_key text,p_control_key text,p_category text,p_status text,p_severity text,p_statement text,p_evidence jsonb default '{}'::jsonb,p_source_url text default null,p_expires_at timestamptz default null)returns jsonb language plpgsql security definer set search_path='public' as $$declare v_id uuid;v_status text:=upper(coalesce(nullif(trim(p_status),''),'UNKNOWN'));v_severity text:=lower(coalesce(nullif(trim(p_severity),''),'medium'));begin if nullif(trim(p_tenant_id),'') is null or nullif(trim(p_provider_key),'') is null or nullif(trim(p_control_key),'') is null then raise exception 'observation identity required';end if;if v_status not in('VERIFIED','PARTIAL','OPEN','UNKNOWN','STALE') then raise exception 'invalid status';end if;if v_severity not in('critical','high','medium','low','info') then raise exception 'invalid severity';end if;insert into public.security_trust_provider_observation_v1(tenant_id,provider_key,control_key,category,status,severity,statement,evidence,source_url,expires_at)values(trim(p_tenant_id),trim(p_provider_key),trim(p_control_key),coalesce(nullif(trim(p_category),''),'provider'),v_status,v_severity,coalesce(nullif(trim(p_statement),''),'No statement supplied'),coalesce(p_evidence,'{}'::jsonb),nullif(trim(p_source_url),''),p_expires_at)returning observation_id into v_id;return jsonb_build_object('observationId',v_id,'status',v_status,'recordedAt',now());end $$;revoke all on function public.record_security_trust_observation_v1(text,text,text,text,text,text,text,jsonb,text,timestamptz) from public,anon,authenticated;grant execute on function public.record_security_trust_observation_v1(text,text,text,text,text,text,text,jsonb,text,timestamptz) to service_role;
insert into public.security_trust_provider_observation_v1(tenant_id,provider_key,control_key,category,status,severity,statement,evidence,source_url,expires_at)select 'canonical','netlify','owner_mfa','identity_access','VERIFIED','low','Netlify owner MFA is enabled and Team PrinsenCo enforces MFA according to management-plane readback.',jsonb_build_object('mfaEnabled',true,'teamMfaEnforced',true,'evidenceClass','provider_management_readback'),'https://www.netlify.com/security/',now()+interval '7 days' where not exists(select 1 from public.security_trust_provider_observation_v1 where tenant_id='canonical' and provider_key='netlify' and control_key='owner_mfa');
insert into public.security_trust_provider_observation_v1(tenant_id,provider_key,control_key,category,status,severity,statement,evidence,source_url,expires_at)select 'canonical','notion','workspace_identity_inventory','identity_access','OPEN','medium','Workspace inventory contains one person and multiple bots/integrations; stale integrations require periodic least-privilege review.',jsonb_build_object('evidenceClass','provider_management_readback','reviewRequired',true),'https://www.notion.com/help/security-and-privacy',now()+interval '7 days' where not exists(select 1 from public.security_trust_provider_observation_v1 where tenant_id='canonical' and provider_key='notion' and control_key='workspace_identity_inventory');
insert into public.security_trust_provider_observation_v1(tenant_id,provider_key,control_key,category,status,severity,statement,evidence,source_url,expires_at)select 'canonical','powerhouse','isolated_restore_dr_exercise','resilience_recovery','OPEN','high','Backup availability exists, but isolated restore plus measured RTO/RPO remains open until runtime proof exists.',jsonb_build_object('evidenceClass','repository_security_operations_contract'),'https://github.com/arthurprinsen-ai/Bedrijfsgeheugen/blob/main/brain/production/security-operations-closure-v1.json',now()+interval '14 days' where not exists(select 1 from public.security_trust_provider_observation_v1 where tenant_id='canonical' and provider_key='powerhouse' and control_key='isolated_restore_dr_exercise');
create or replace function public.refresh_security_trust_snapshot_v1(p_tenant_id text)returns jsonb language plpgsql security definer set search_path='public' as $$declare v_tenant text:=coalesce(nullif(trim(p_tenant_id),''),'canonical');v_tables int:=0;v_rls int:=0;v_rls_no_policy int:=0;v_secdef_functions int:=0;v_secdef_exposed int:=0;v_mutable_search int:=0;v_secdef_views int:=0;v_api_matviews int:=0;v_observations jsonb:='[]';v_providers jsonb:='[]';v_frameworks jsonb:='[]';v_domains jsonb:='[]';v_findings jsonb:='[]';v_summary jsonb:='{}';v_result jsonb;v_open int:=0;v_stale int:=0;v_verified int:=0;v_sovereignty_violations int:=0;v_db_findings int:=0;begin
select count(*),count(*) filter(where c.relrowsecurity) into v_tables,v_rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p');select count(*) into v_rls_no_policy from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p') and c.relrowsecurity and not exists(select 1 from pg_policy pol where pol.polrelid=c.oid);select count(*) filter(where p.prosecdef),count(*) filter(where p.prosecdef and(has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))),count(*) filter(where p.prosecdef and coalesce(array_to_string(p.proconfig,','),'') not ilike '%search_path=%') into v_secdef_functions,v_secdef_exposed,v_mutable_search from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public';select count(*) into v_secdef_views from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v' and not(coalesce(c.reloptions,'{}'::text[])@>array['security_invoker=true']::text[]);select count(*) into v_api_matviews from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='m' and(has_table_privilege('anon',c.oid,'SELECT') or has_table_privilege('authenticated',c.oid,'SELECT'));
with latest as(select distinct on(provider_key,control_key)provider_key,control_key,category,severity,statement,evidence,source_url,observed_at,expires_at,case when expires_at is not null and expires_at<now() then 'STALE' else status end effective_status from public.security_trust_provider_observation_v1 where tenant_id in('canonical',v_tenant) order by provider_key,control_key,case when tenant_id=v_tenant then 0 else 1 end,observed_at desc)select coalesce(jsonb_agg(jsonb_build_object('providerKey',provider_key,'controlKey',control_key,'category',category,'status',effective_status,'severity',severity,'statement',statement,'evidence',evidence,'sourceUrl',source_url,'observedAt',observed_at,'expiresAt',expires_at)order by category,provider_key,control_key),'[]'),count(*) filter(where effective_status='VERIFIED'),count(*) filter(where effective_status='STALE'),count(*) filter(where effective_status in('OPEN','UNKNOWN','STALE')) into v_observations,v_verified,v_stale,v_open from latest;
select coalesce(jsonb_agg(jsonb_build_object('providerKey',provider_key,'name',display_name,'serviceKind',service_kind,'customerDataExposure',customer_data_exposure,'storageScope',storage_scope,'processingScope',processing_scope,'primaryRegion',primary_region,'crossBorderTransfer',cross_border_transfer,'trainingUse',training_use,'retention',retention_summary,'subprocessors',subprocessors,'evidenceUrls',evidence_urls,'evidenceStatus',evidence_status,'runtimeStatus',runtime_status,'checkedAt',evidence_checked_at)order by display_name),'[]') into v_providers from public.data_sovereignty_provider_registry_v1 where customer_visible=true;select coalesce(jsonb_array_length(violations),0) into v_sovereignty_violations from public.data_sovereignty_snapshot_v1 where tenant_id=v_tenant;
v_db_findings:=(case when v_secdef_exposed>0 then 1 else 0 end)+(case when v_secdef_views>0 then 1 else 0 end)+(case when v_mutable_search>0 then 1 else 0 end)+(case when v_api_matviews>0 then 1 else 0 end);
if v_secdef_exposed>0 then v_findings:=v_findings||jsonb_build_array(jsonb_build_object('id','DB-PRIVILEGED-RPC-EXPOSURE','title','Privileged SECURITY DEFINER functions executable via API roles','severity','critical','status','OPEN','reason',v_secdef_exposed||' SECURITY DEFINER function(s) are executable by anon/authenticated roles.','domain','database'));end if;if v_secdef_views>0 then v_findings:=v_findings||jsonb_build_array(jsonb_build_object('id','DB-SECURITY-DEFINER-VIEWS','title','Views without explicit security_invoker','severity','high','status','OPEN','reason',v_secdef_views||' public view(s) do not explicitly use security_invoker=true.','domain','database'));end if;if v_mutable_search>0 then v_findings:=v_findings||jsonb_build_array(jsonb_build_object('id','DB-MUTABLE-SEARCH-PATH','title','SECURITY DEFINER functions without fixed search_path','severity','medium','status','OPEN','reason',v_mutable_search||' privileged function(s) need explicit search_path hardening.','domain','database'));end if;if v_api_matviews>0 then v_findings:=v_findings||jsonb_build_array(jsonb_build_object('id','DB-API-MATERIALIZED-VIEWS','title','Materialized views exposed to API roles','severity','medium','status','OPEN','reason',v_api_matviews||' materialized view(s) are selectable by anon/authenticated roles.','domain','database'));end if;
with latest as(select distinct on(provider_key,control_key)provider_key,control_key,category,severity,statement,case when expires_at is not null and expires_at<now() then 'STALE' else status end effective_status from public.security_trust_provider_observation_v1 where tenant_id in('canonical',v_tenant) order by provider_key,control_key,case when tenant_id=v_tenant then 0 else 1 end,observed_at desc)select v_findings||coalesce(jsonb_agg(jsonb_build_object('id',upper(provider_key||'-'||control_key),'title',statement,'severity',severity,'status',effective_status,'reason',statement,'domain',category))filter(where effective_status in('OPEN','UNKNOWN','STALE')),'[]') into v_findings from latest;
v_frameworks:=jsonb_build_array(jsonb_build_object('id','NIS2_CBW','label','NIS2 / Cyberbeveiligingswet','role','EU/NL cybersecurity regulation','applicability','SCOPE_DECISION_REQUIRED','sourceUrl','https://eur-lex.europa.eu/eli/dir/2022/2555'),jsonb_build_object('id','NIS','label','NIS (legacy)','role','historical predecessor','applicability','SUPERSEDED_BY_NIS2','sourceUrl','https://eur-lex.europa.eu/eli/dir/2022/2555'),jsonb_build_object('id','GDPR_AVG','label','AVG / GDPR','role','privacy regulation','applicability','WHEN_PERSONAL_DATA_PROCESSED','sourceUrl','https://eur-lex.europa.eu/eli/reg/2016/679/oj'),jsonb_build_object('id','EU_AI_ACT','label','EU AI Act','role','AI regulation','applicability','USE_CASE_AND_ROLE_DEPENDENT','sourceUrl','https://eur-lex.europa.eu/eli/reg/2024/1689/oj'),jsonb_build_object('id','ISO27001','label','ISO/IEC 27001:2022','role','ISMS certification framework','applicability','BENCHMARK_NOT_CERTIFICATION_CLAIM','sourceUrl','https://www.iso.org/standard/27001'),jsonb_build_object('id','SOC2','label','SOC 2','role','provider assurance / audit framework','applicability','PROVIDER_ASSURANCE_ONLY_UNLESS_OWN_AUDIT','sourceUrl','https://supabase.com/docs/guides/security/soc-2-compliance'),jsonb_build_object('id','NIST_CSF_2','label','NIST CSF 2.0','role','cybersecurity risk framework','applicability','BEST_PRACTICE','sourceUrl','https://www.nist.gov/cyberframework'),jsonb_build_object('id','CIS_CONTROLS_V8','label','CIS Controls v8','role','security safeguards benchmark','applicability','BEST_PRACTICE','sourceUrl','https://www.cisecurity.org/controls/v8'),jsonb_build_object('id','OWASP_ASVS_5','label','OWASP ASVS 5','role','application security verification','applicability','WEB_APP_BEST_PRACTICE','sourceUrl','https://owasp.org/projects/asvs'),jsonb_build_object('id','DORA','label','DORA','role','financial-sector operational resilience regulation','applicability','SECTOR_SCOPE_REQUIRED','sourceUrl','https://eur-lex.europa.eu/eli/reg/2022/2554/oj'),jsonb_build_object('id','CRA','label','Cyber Resilience Act','role','product cybersecurity regulation','applicability','PRODUCT_ROLE_SCOPE_REQUIRED','sourceUrl','https://eur-lex.europa.eu/eli/reg/2024/2847/oj'));
v_domains:=jsonb_build_array(jsonb_build_object('id','identity_access','icon','◎','label','Identity & access','status',case when exists(select 1 from jsonb_array_elements(v_observations)x where x->>'category'='identity_access' and x->>'status' in('OPEN','STALE','UNKNOWN'))then'OPEN'else'PARTIAL'end,'summary','Authenticatie, tenantisolatie, MFA, serviceaccounts en least privilege.','detail','Provider-IAM evidence heeft freshness en verloopt als readback niet wordt vernieuwd.'),jsonb_build_object('id','database','icon','▦','label','Database & API','status',case when v_db_findings>0 then'ACTION_REQUIRED'else'VERIFIED'end,'summary',v_rls||'/'||v_tables||' public tabellen hebben RLS; privileged exposure wordt live berekend.','detail','Live catalogus: SECURITY DEFINER, API EXECUTE, search_path, RLS/policies en materialized-view exposure.'),jsonb_build_object('id','application','icon','◇','label','Applicatie & portal','status','PARTIAL','summary','Authenticated routes, tenant-boundaries en secure-by-default UI.','detail','OWASP/ASVS-alignment is technisch; onafhankelijke applicatiecertificering wordt niet geclaimd.'),jsonb_build_object('id','data_ai','icon','✦','label','Data & AI','status',case when v_sovereignty_violations>0 then'OPEN'else'PARTIAL'end,'summary','Dataresidentie, AI-routes, training-use, subprocessors en cross-border transfers.','detail','Data & AI Sovereignty blijft de bron voor opslag/verwerking/AI-providertruth.'),jsonb_build_object('id','sdlc_supply_chain','icon','⌘','label','Code, CI/CD & supply chain','status','PARTIAL','summary','GitHub, CodeQL, protected delivery en deploy lineage.','detail','Code/deploy evidence blijft SHA-bound.'),jsonb_build_object('id','infrastructure','icon','⬡','label','Hosting & infrastructuur','status','PARTIAL','summary','Netlify, Supabase, regio en platform boundaries.','detail','Providercertificeringen ondersteunen assurance maar maken Bedrijfsgeheugen niet gecertificeerd.'),jsonb_build_object('id','monitoring_incident','icon','△','label','Monitoring & incident','status','PARTIAL','summary','Audit, logging, detectie, incidentrespons en herstelverplichtingen.','detail','NIST CSF Govern/Identify/Protect/Detect/Respond/Recover is de uitleglaag.'),jsonb_build_object('id','resilience_recovery','icon','↻','label','Continuïteit & herstel','status',case when exists(select 1 from jsonb_array_elements(v_observations)x where x->>'category'='resilience_recovery' and x->>'status'='OPEN')then'OPEN'else'PARTIAL'end,'summary','Backups, restore, RTO/RPO, failover en recovery proof.','detail','Backup availability en geïsoleerde restore zijn aparte controls.'),jsonb_build_object('id','privacy_compliance','icon','▣','label','Privacy, governance & compliance','status','PARTIAL','summary','AVG, AI Act, NIS2/Cbw, ISO, SOC 2, DORA, CRA en audit evidence.','detail','Alignment, juridische scope en onafhankelijke certificering blijven gescheiden.'));
v_summary:=jsonb_build_object('overallStatus',case when jsonb_array_length(v_findings)>0 then'ACTION_REQUIRED'else'PARTIAL'end,'verified',v_verified,'stale',v_stale,'openObservationCount',v_open,'databaseFindings',v_db_findings,'tableCount',v_tables,'rlsEnabled',v_rls,'rlsEnabledNoPolicy',v_rls_no_policy,'securityDefinerFunctions',v_secdef_functions,'securityDefinerExposed',v_secdef_exposed,'securityDefinerViews',v_secdef_views,'mutableSearchPath',v_mutable_search,'apiMaterializedViews',v_api_matviews,'sovereigntyViolations',v_sovereignty_violations,'truthPolicy','measured_or_evidence_backed_else_unknown','certificationClaim','NONE');
insert into public.security_trust_snapshot_v1(tenant_id,summary,domains,providers,frameworks,open_findings,generated_at)values(v_tenant,v_summary,v_domains,v_providers,v_frameworks,v_findings,now())on conflict(tenant_id)do update set summary=excluded.summary,domains=excluded.domains,providers=excluded.providers,frameworks=excluded.frameworks,open_findings=excluded.open_findings,generated_at=excluded.generated_at;select jsonb_build_object('tenantId',tenant_id,'summary',summary,'domains',domains,'providers',providers,'frameworks',frameworks,'openFindings',open_findings,'generatedAt',generated_at)into v_result from public.security_trust_snapshot_v1 where tenant_id=v_tenant;return v_result;end $$;revoke all on function public.refresh_security_trust_snapshot_v1(text) from public,anon,authenticated;grant execute on function public.refresh_security_trust_snapshot_v1(text) to service_role;
create or replace function public.powerhouse_refresh_data_sovereignty_v1()returns jsonb language plpgsql security definer set search_path='public' as $$declare r record;v_count int:=0;v_blocked int:=0;v_security int:=0;v_snapshot jsonb;v_security_snapshot jsonb;begin for r in select tenant_id from public.tenant_data_sovereignty_policy_v1 union select 'canonical'::text loop v_snapshot:=public.refresh_data_sovereignty_snapshot_v1(r.tenant_id);v_security_snapshot:=public.refresh_security_trust_snapshot_v1(r.tenant_id);v_count:=v_count+1;v_security:=v_security+1;if coalesce((v_snapshot#>>'{summary,policySatisfied}')::boolean,false)=false then v_blocked:=v_blocked+1;end if;end loop;return jsonb_build_object('refreshed',v_count,'securitySnapshotsRefreshed',v_security,'policyViolations',v_blocked,'refreshedAt',now(),'contract','data-sovereignty-security-trust-control-plane-v1');end $$;revoke all on function public.powerhouse_refresh_data_sovereignty_v1() from public,anon,authenticated;grant execute on function public.powerhouse_refresh_data_sovereignty_v1() to service_role;select public.refresh_data_sovereignty_snapshot_v1('canonical');select public.refresh_security_trust_snapshot_v1('canonical');